import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';
import { filterProfanity } from '../../../../backend/korean_bad_words';  // 욕설 필터링 라이브러리

const Chat = () => {
  const location = useLocation();
  const { personality, gender } = location.state || {};  // '/settings'에서 전달된 값
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [error, setError] = useState(null);

  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    // 욕설이 포함되어 있는지 확인
    if (filterProfanity(userInput)) {
      setError("욕설은 사용할 수 없습니다.");  // 욕설 경고 메시지
      setUserInput("");  // 사용자 입력 초기화
      return;
    }

    // 사용자의 메시지 추가
    setChatHistory((prevHistory) => [
      ...prevHistory,
      { sender: "user", message: userInput },
    ]);

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ user_input: userInput, personality, gender }),
      });

      if (!response.ok) {
        throw new Error("Failed to fetch response from the server");
      }

      const data = await response.json();
      const chatbotMessage = typeof data.response === "string"
        ? data.response
        : JSON.stringify(data.response);

      // 챗봇 응답을 chatHistory에 추가
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "chatbot", message: chatbotMessage },
      ]);
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError("챗봇 응답을 처리하는 중 오류가 발생했습니다.");  // 에러 상태 업데이트
    }

    // 사용자 입력 초기화
    setUserInput("");
  };

  return (
    <div>
      {/* 에러 메시지 표시 */}
      {error && <div style={{ color: "red", marginBottom: "10px" }}>{error}</div>}

      {/* 챗봇 대화 내용 표시 */}
      <div>
        {chatHistory.map((chat, index) => (
          <div key={index} className={chat.sender} style={{ margin: "10px 0" }}>
            <strong>{chat.sender === "user" ? "User" : "Chatbot"}:</strong>
            <span>{chat.message}</span>
          </div>
        ))}
      </div>

      {/* 사용자 입력 폼 */}
      <div>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}  // 사용자 입력값 변경
          style={{ width: "80%", padding: "10px", marginRight: "10px" }}
        />
        <button 
          onClick={handleSendMessage} 
          style={{ padding: "10px", backgroundColor: "#4CAF50", color: "white", border: "none", cursor: "pointer" }}
        >
          전송
        </button>
      </div>
    </div>
  );
};

export default Chat;
